import {
  ExportOutlined,
  CloseSquareOutlined,
  EyeOutlined,
  PullRequestOutlined,
  RollbackOutlined,
} from "@ant-design/icons";
import "./CardRegistration.css";

const ReceivedTable = ({
  t,
  dataSource,
  loading,
  rejectShipment,
  viewHistory,
  openModal,
  surPlusRequest,
}) => {
  const [searchedColumn, setSearchedColumn] = useState('');
  const spinText = 'Loading...';
  const [searchText, setSearchText] = useState('');
  const searchInput = useRef(null);
  const [expandedRowKeys, setExpandedRowKeys] = useState([]);
  const department = localStorage.JWTDepartment;
  const { headerColumns, bodyColumns, bodyColumnsReceived } =
    useRegistrationColumns(t, setSearchText, setSearchedColumn, searchInput);

  const handleExpand = (expanded, record) => {
    setExpandedRowKeys(expanded ? [record.key] : []);
  };

  // Sortiranje: svi redovi sa ostatus === "15" idu na vrh, ostali zadr_avaju originalni redosled
  const sortedData = [...dataSource].sort((a, b) => {
    const aCritical = a.ostatus === "15";
    const bCritical = b.ostatus === "15";

    if (aCritical && !bCritical) return -1;
    if (!aCritical && bCritical) return 1;

    return 0; // zadr_i originalni redosled ako oba nisu critical
  });

  const actionBodyColumn = {
    title: t('common:action'),
    key: 'action',
    dataIndex: 'action',
    render: (value, record) => (
      <>
        <Tooltip title={t("common:tooltipHistory")}>
          <Button
            type="primary"
            icon={<EyeOutlined />}
           // danger={record.ostatus === "15"} // Ant Design danger prop
            onClick={() => viewHistory(record)}
            style={{ marginLeft: "3px" }}
          />
        </Tooltip>
        {"    "}
        {record.branchDelivery === department && (
          <Tooltip title={t("common:tooltipRedirect")}>
            <Button
              type="primary"
              icon={<PullRequestOutlined />}
              onClick={() => openModal(record)}
              style={{ marginRight: "3px", background: "#ffa500" }}
            />
          </Tooltip>
        )}

        {record.obranch !== record.branchDelivery &&
          department === record.obranch &&
          department !== record.branchDelivery && (
            <Popconfirm
              title={t("common:surplusShipmentRequest")}
              onConfirm={() => surPlusRequest(record)}
              okText={t('common:btnYes')}
              cancelText={t('common:btnNo')}
            >
              <Tooltip title={t("common:tooltipZahtev")}>
                <Button
                  type="primary"
                  icon={<RollbackOutlined />}
                  style={{ marginRight: "3px", background: "#ff5733" }}
                />
              </Tooltip>
            </Popconfirm>
          )}
      </>
    ),
  };

  return (
    <>
      <div className="table-responsive" style={{ marginTop: '30px' }}>
        <Table
          size="small"
          columns={[...bodyColumnsReceived, actionBodyColumn]}
          dataSource={sortedData} // koristi sortirane podatke
          rowKey="id"
          locale={{
            emptyText: <Empty description={t('common:noData')} />,
          }}
          pagination={{ pageSize: 20 }}
          loading={{
            indicator: <Spin size="large" />,
            spinning: loading,
            tip: spinText,
          }}
        />
      </div>
    </>
  );
};

export default withTranslation(['cardRegistration'])(ReceivedTable);

