// ShipmentTable.js
import React, { useState, useRef, useEffect } from 'react';
import { Table, Spin, Button, Popconfirm, Empty, Tooltip } from 'antd';
import { withTranslation } from 'react-i18next';
import useRegistrationColumns from './columns';
import {
  ArrowDownOutlined,
  CloseSquareOutlined,
} from '@ant-design/icons';
import './CardRegistration.css';

const ShipmentTable = ({
  t,
  dataSource,
  loading,
  acceptAllShipment,
  acceptShipment,
  rejectShipment,
  surPlusShip,
}) => {
  const [department, setDepartment] = useState(localStorage.getItem("JWTDepartment"));
  const [expandedRowKeys, setExpandedRowKeys] = useState([]);
  const [expandedPageSize, setExpandedPageSize] = useState(10);

  useEffect(() => {
    setDepartment(localStorage.getItem("JWTDepartment"));
  }, []);

  const searchInput = useRef(null);
  const { headerColumns, bodyColumns } = useRegistrationColumns(
    t,
    () => {},
    () => {},
    searchInput,
  );

  const handleExpand = (expanded, record) => {
    setExpandedRowKeys(expanded ? [record.key] : []);
  };

  const handleExpandedPageSizeChange = (current, size) => {
    setExpandedPageSize(size);
  };

  const normalizeBranch = (value) => {
    if (value === null || value === undefined) return "";
    const strValue = String(value).trim();
    if (/^\d+$/.test(strValue)) {
      const stripped = strValue.replace(/^0+/, "");
      return stripped === "" ? "0" : stripped;
    }
    return strValue.toUpperCase();
  };

  const isSameBranch = (branchValue) =>
    normalizeBranch(branchValue) === normalizeBranch(department);

  const actionHeaderColumn = {
    title: t("common:action"),
    key: "action",
    dataIndex: "action",
    render: (value, record) => {
      console.log("ShipmentTable header branch compare:", {
        department,
        recordBranch: record.branch,
        recordObranch: record.obranch,
        opxcode: record.opxcode,
      });
      const isMigration = (record.opxcode || "").toUpperCase().includes("MIGRACIJA");
      const isDisabled = !isSameBranch(record.branch) || isMigration;

      return (
        <Popconfirm
          title={`${t("common:confirmAcceptAllCib")} (ID: ${record.cibBatch})?`}
          onConfirm={() => acceptAllShipment(record)}
          disabled={isDisabled}
        >
          <Button
            type="primary"
            icon={<ArrowDownOutlined />}
            disabled={isDisabled}
          >
            {t("common:btnAcceptAll")}
          </Button>
        </Popconfirm>
      );
    },
  };

  const actionBodyColumn = {
    title: t('common:action'),
    key: 'action',
    dataIndex: 'action',
    render: (value, record) => (
      <> 
        {console.log("ShipmentTable row branch compare:", {
          department,
          recordObranch: record.obranch,
          recordBranch: record.branch,
          opxcode: record.opxcode,
        })}
        <Tooltip title={t("common:tooltipPrijem")}>
          <Button 
            type="primary" 
            icon={<ArrowDownOutlined />} 
            onClick={() => acceptShipment(record)}
            disabled={!isSameBranch(record.obranch)}
          />
        </Tooltip>
        <Popconfirm 
          title={t('common:rejectShipment')} 
          onConfirm={() => rejectShipment(record)} 
          cancelText={t('common:btnCancel')} 
          showCancel={true} 
        >
          <Tooltip title={t("common:tooltipManjak")}>
            <Button 
              type="primary" 
              icon={<CloseSquareOutlined />} 
              style={{ marginLeft: "3px", background: "#FF3D33" }} 
              disabled={!isSameBranch(record.obranch)} 
            /> 
          </Tooltip>
        </Popconfirm>
      </>
    )
  };

  return (
    <div className="table-responsive" style={{ marginTop: '30px' }}>
      <Table
        className="ant-border-space"
        size="small"
        columns={[...headerColumns, actionHeaderColumn]}
        expandable={{
          expandedRowRender: (record) => (
            <Table
              columns={[...bodyColumns, actionBodyColumn]}
              dataSource={record.content}
              pagination={{
                pageSize: expandedPageSize,
                showSizeChanger: true,
                pageSizeOptions: ['10', '20', '50'],
                onShowSizeChange: handleExpandedPageSizeChange,
                showTotal: (total, range) => `${range[0]}-${range[1]} od ukupno ${total} stavki`,
              }}
              rowKey="binId"
            />
          ),
          onExpand: handleExpand,
          expandedRowKeys: expandedRowKeys,
          rowExpandable: (record) => record.content.length > 0,
        }}
        locale={{
          emptyText: <Empty description={t('title')} />,
        }}
        dataSource={dataSource.map((item, index) => ({
          ...item,
          key: index,
        }))}
        pagination={{
          pageSize: 20,
          showSizeChanger: true,
          pageSizeOptions: ['10', '20', '50', '100'],
          showTotal: (total, range) => `${range[0]}-${range[1]} od ukupno ${total} po­iljki`,
        }}
        loading={{
          indicator: <Spin size="large" />,
          spinning: loading,
          tip: 'Loading...',
        }}
      />
    </div>
  );
};

export default withTranslation(['cardRegistration'])(ShipmentTable);

