import React, { useState, useEffect } from "react";
import ShipmentTable from "../../components/CardRegistration/ShipmentTable";
import SearchCard from "../../components/CardRegistration/SearchCard";
import { Col, Card, Row, ConfigProvider, Badge, Popconfirm } from "antd";
import { withTranslation } from "react-i18next";
import { getAllShipmentForBranch,searchByForm, acceptAllShipment, acceptShipment, redirectShipment, refuseShipment, surPlusAlert, surPlusStorno } from "../../services/cardRegistration/service";
import RedirectModal from "../../components/CardRegistration/RedirectModal";
import { constant } from "lodash";
import Notification from "../../components/Notification/Notification";

const ShipmentPage = ({ t, type }) => {
  const [loading, setLoading] = useState(false);
  const [dataSource, setDataSource] = useState([]);
  const isDataSourceEmpty = dataSource.length === 0;
  const department = localStorage.JWTDepartment;
  const username = localStorage.JWTUsername;

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedBranch, setSelectedBranch] = useState();

  const groupByPxCode = (data) => {
    const a = data.reduce((acc, item) => {

      const { opxcode } = item;
      if (!acc[opxcode]) {
        acc[opxcode] = {
          branch: item.obranch,
          countOfCard: 0,
          countOfPin: 0,
          count: 0,
          opxcode: opxcode,
          odatum: null,
          content: [],
        };
      }
      const currentMax = acc[opxcode].odatum
        ? new Date(acc[opxcode].odatum)
        : new Date(0);

      // Preferiraj oDatum/ODatum iz API-ja; fallback na updatedAt
      const itemDateRaw = item.odatum ?? item.oDatum ?? item.ODatum ?? item.updatedAt ?? null;
      const itemDate = itemDateRaw ? new Date(itemDateRaw) : new Date(0);

      if (!itemDateRaw) {
        console.warn("ShipmentPage: nedostaje datum za stavku", { opxcode, item });
      }

      if (itemDate > currentMax) {
        acc[opxcode].odatum = itemDateRaw;
      }

      acc[opxcode].content.push(item);
      if (item.type === "c") acc[opxcode].countOfCard += 1;
      if (item.type === "p") acc[opxcode].countOfPin += 1;
      acc[opxcode].count = acc[opxcode].countOfCard + acc[opxcode].countOfPin;
      return acc;
    }, {});
    return Object.values(a);
  };

  const fetchAll = async () => {
    setLoading(true);
    try {
      const response = await getAllShipmentForBranch();
      const data = groupByPxCode(response.data);
      setDataSource(data);
      setLoading(false);
    } catch (ex) {
      setLoading(false);
      Notification(t("cardRegistration:error:title"), t("cardRegistration:error:msg"), "error", "topRight");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchAll();
  }, [t, type]);

  const searchByCriteria = async (form) => {
    setLoading(true);
    const response = await searchByForm(form);
    const data = groupByPxCode(response.data);
    setDataSource(data);
    setLoading(false);
  };

  const resetSearch = async (form) => {
    form.resetFields();
    fetchAll();
  };

  const acceptAll = async (data) => {
    const updatedData = data.content.map((item) => ({
      ...item,
      updatedBy: username,
    }));
    const response = await acceptAllShipment(updatedData);
    if (response.data) Notification(t("cardRegistration:success:title"), t("cardRegistration:success:msg"), "success", "topRight", 2);

    fetchAll();
  };

  const accept = async (data) => {
    try {
      const response = await acceptShipment(data);
      fetchAll();
      if (response.data) Notification(t("cardRegistration:success:title"), t("cardRegistration:success:msg"), "success", "topRight", 2);
    } catch (ex) {
      console.log(ex);
    }
  };

  const openModal = async (record) => {
    setIsModalOpen(true);
    setSelectedBranch(record);
  };

  const sendToAnotherBranch = async (value) => {
    const newObject = {
      ...selectedBranch,
      obranch: value.newBranch,
      opxcode: value.newPxCode,
      updatedBy: value.user,
    };
    try {
      const response = await redirectShipment(newObject);
      fetchAll();
      if (response.data) Notification(t("cardRegistration:success:title"), t("cardRegistration:success:msg"), "success", "topRight", 2);
    } catch (ex) {
      console.log(ex);
    }
    handleCancel();
  };

  const handleCancel = () => {
    setIsModalOpen(false);
  };

  const rejectShipment = async (data) => {
    try {
      const response = await refuseShipment(data);
      fetchAll();
      if (response.data) Notification(t("cardRegistration:success:title"), t("cardRegistration:success:msg"), "success", "topRight", 2);
    } catch (ex) {
      console.log(ex);
    }
  };
  const surPlusShip = async (data) => {
    try {
      const response = await surPlusAlert(data);
      fetchAll();
      if (response.data) Notification(t("surPlusShipment:successSurPlusRequest:title"), t("surPlusShipment:successSurPlusReques:msg"), "successSurPlusRequest", "topRight", 2);
    } catch (ex) {
      console.log(ex);
    }
  };

  return (
    <>
      <ConfigProvider theme={{ token: { colorPrimary: "#22beed" } }}>
        <RedirectModal isModalOpen={isModalOpen} closeModal={handleCancel} sendToAnotherBranch={sendToAnotherBranch} />
        <Card
          style={{ borderTop: "5px solid #22beed" }}
          className="header-solid mb-24"
          title={
            <>
              <Badge status="processing" size="large" color="#ffa500" />
              <h3 className="font-semibold" style={{ display: "inline", paddingLeft: 10 }}>
                {department}
              </h3>
            </>
          }
        >
          <Row gutter={[24, 24]}>
            <Col>
              <Col className="card-project">
                <SearchCard searchByCriteria={searchByCriteria} isDataSourceEmpty={isDataSourceEmpty} resetSearch={resetSearch} />
              </Col>
            </Col>
          </Row>

          <Col>
            <ShipmentTable dataSource={dataSource} loading={loading} acceptAllShipment={acceptAll} acceptShipment={accept} rejectShipment={rejectShipment} />
          </Col>
        </Card>
      </ConfigProvider>
    </>
  );
};

export default withTranslation(["cardRegistration"])(ShipmentPage);

